(39561, 'Job 38:41', 'Job', 38, 41, 'کارغانو دپاره د خوراک بندوبست څوک کوى، کله چې د هغوئ بچى خُدائ پاک ته ژړا کوى، او د خوراک د نشتوالى په وجه سرګردانه ګرځى؟', 'کارغانو دپاره د خوراک بندوبست چوک کوی، کله چې د هغوی بچی خدای پاک ته ژرا کوی، او د خوراک د نشتوالی په وجه سرګردانه ګرجی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_38_41.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237840, 1761237840),
(39562, 'Nehemiah 9:3', 'Nehemiah', 9, 3, 'هغوی درې ساعته ولاړ وو او د خپل څښتن خدای تورات ته یې غوږ نیولی ؤ او درې ساعته نور یې په خپلو ګناهونو باندې اقرار وکړ او د خپل څښتن خدای عبادت یې وکړ.', 'هغوی درې ساعته ولار وو او د خپل چشتن خدای تورات ته یې غوز نیولی و او درې ساعته نور یې په خپلو ګناهونو باندې اقرار وکر او د خپل چشتن خدای عبادت یې وکر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39563, 'Nehemiah 9:4', 'Nehemiah', 9, 4, 'یشوع، باني، قدمي ییل، شبنیا، بوني، شربیا، باني او کناني په هغه منبر باندې ودرېدل چې د لاویانو دپاره ؤ او په لوړ اواز یې خپل څښتن خدای ته زارۍ وکړې.', 'یشوع، بانی، قدمی ییل، شبنیا، بونی، شربیا، بانی او کنانی په هغه منبر باندې ودرېدل چې د لاویانو دپاره و او په لور اواز یې خپل چشتن خدای ته زاری وکرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39564, 'Nehemiah 9:5', 'Nehemiah', 9, 5, 'دغو نورو لاویانو خلکو ته د عبادت دپاره بلنه ورکړه: یشوع، قدمي ییل، باني، حشبنیا، شربیا، هودیا، شبنیا او فتحیا. هغوی وویل: پاڅېږئ وکړئ ستاینه د خپل څښتن خدای ستاینه وکړئ د هغه د تل دپاره هر یو دې وکړي د هغه د جلالي نوم صفت ثنا دې وي ستا پر جلاله نوم ته چې لوی دی ټولو صفتونو څخه', 'دغو نورو لاویانو خلکو ته د عبادت دپاره بلنه ورکره: یشوع، قدمی ییل، بانی، حشبنیا، شربیا، هودیا، شبنیا او فتحیا. هغوی وویل: پاچېزی وکری ستاینه د خپل چشتن خدای ستاینه وکری د هغه د تل دپاره هر یو دې وکری د هغه د جلالی نوم صفت ثنا دې وی ستا پر جلاله نوم ته چې لوی دی تولو صفتونو چخه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39565, 'Nehemiah 9:6', 'Nehemiah', 9, 6, 'ته څښتن یې یوازې ته څښتن یې تا دي جوړ کړي اسمانونه ټول د ستورو سره تا پیدا کړې ځمکه، بحیره او هر څه چې دي هغو کې تا وربخښلی دی ژوندون ټولو ته تاته سجده کړي ستا عبادت کړي اسماني ځواکونه', 'ته چشتن یې یوازې ته چشتن یې تا دی جور کری اسمانونه تول د ستورو سره تا پیدا کرې جمکه، بحیره او هر چه چې دی هغو کې تا وربخشلی دی ژوندون تولو ته تاته سجده کری ستا عبادت کری اسمانی جواکونه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39566, 'Nehemiah 9:7', 'Nehemiah', 9, 7, 'ته یې هغه څښتن خدای چا چې کړ غوره ابرام تا راوویست هغه د کلدانیانو د اور د ښار څخه او د هغه نوم دې ابراهیم کېښود', 'ته یې هغه چشتن خدای چا چې کر غوره ابرام تا راوویست هغه د کلدانیانو د اور د شار چخه او د هغه نوم دې ابراهیم کېشود', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39567, 'Nehemiah 9:8', 'Nehemiah', 9, 8, 'ته شوې پوه چې هغه تاته وفادار دی او تا وکړ د هغه سره لوظ تا وعده وکړه چې اولادې ته د هغه به ورکړې د کنعانیانو ځمکه هم د حیتیانو، اموریانو ځمکه د فرزیانو، یبوسیانو، جرجاشیانو ځمکه ته ودرېدلې خپله وعده باندې ځکه چې ته یې وفادار', 'ته شوې پوه چې هغه تاته وفادار دی او تا وکر د هغه سره لوظ تا وعده وکره چې اولادې ته د هغه به ورکرې د کنعانیانو جمکه هم د حیتیانو، اموریانو جمکه د فرزیانو، یبوسیانو، جرجاشیانو جمکه ته ودرېدلې خپله وعده باندې جکه چې ته یې وفادار', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39568, 'Nehemiah 9:9', 'Nehemiah', 9, 9, 'تا ولید مصر کې زمونږه د نیکونو کړاو کله چې وو هغوی سرې بحیرې سره تا واورېدلې چې وهلې هغوی چیغې د کومک په خاطر', 'تا ولید مصر کې زمونزه د نیکونو کراو کله چې وو هغوی سرې بحیرې سره تا واورېدلې چې وهلې هغوی چیغې د کومک په خاطر', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39569, 'Nehemiah 9:10', 'Nehemiah', 9, 10, 'تا وښودلې معجزې حیرانوونکې د فرعون او د هغه د درباریانو خلاف او د هغه وطن د خلکو خلاف ځکه ته پوهېدلې چې وکړ څنګه کبرجن چلند دوی زمونږ نیکونو سره تا وګټلو داسې نوم چې دی پاتې تر ننه پورې', 'تا وشودلې معجزې حیرانوونکې د فرعون او د هغه د درباریانو خلاف او د هغه وطن د خلکو خلاف جکه ته پوهېدلې چې وکر چنګه کبرجن چلند دوی زمونز نیکونو سره تا وګتلو داسې نوم چې دی پاتې تر ننه پورې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39570, 'Nehemiah 9:11', 'Nehemiah', 9, 11, 'لاره دې جوړه کړه خپل قوم ته د بحیرې په منځ کې پورې وتل هغوی د بحیرې له لارې په وچه ځمکه باندې هغوی دې کړل ژورو اوبو ته ګوزار چې ورپسې وو ستا ولس پسې ډوب شول داسې لکه تیږه چې شي ډوبه توفاني بحر کې', 'لاره دې جوره کره خپل قوم ته د بحیرې په منج کې پورې وتل هغوی د بحیرې له لارې په وچه جمکه باندې هغوی دې کرل ژورو اوبو ته ګوزار چې ورپسې وو ستا ولس پسې دوب شول داسې لکه تیزه چې شی دوبه توفانی بحر کې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39571, 'Nehemiah 9:12', 'Nehemiah', 9, 12, 'د ورځې کړه دې لارښوونه ورته د ستنې په شان ورېځ باندې روښانوله ورته لاره دې د شپې له خوا نه په هغه اور باندې چې ؤ د ستنې په شان', 'د ورجې کره دې لارشوونه ورته د ستنې په شان ورېج باندې روشانوله ورته لاره دې د شپې له خوا نه په هغه اور باندې چې و د ستنې په شان', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39572, 'Nehemiah 9:13', 'Nehemiah', 9, 13, 'ته شوې راښکته د سینا غره باندې دوی ته دې وکړلې خبرې له اسمانه څخه ورکړله زده کړه دې هغوی ته د باور نه ډکه ښه قوانین عادلانه دې ورکړل', 'ته شوې راشکته د سینا غره باندې دوی ته دې وکرلې خبرې له اسمانه چخه ورکرله زده کره دې هغوی ته د باور نه دکه شه قوانین عادلانه دې ورکرل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39573, 'Nehemiah 9:14', 'Nehemiah', 9, 14, 'دوی ته دې وښودله خپله سپېڅلې ورځ د سبت ورته دې ورکړل قوانین او تورات په وسیله د خدمتګار خپل موسی', 'دوی ته دې وشودله خپله سپېچلې ورج د سبت ورته دې ورکرل قوانین او تورات په وسیله د خدمتګار خپل موسی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39574, 'Nehemiah 9:15', 'Nehemiah', 9, 15, 'کله چې وږي شول هغوی تا ورته ورکړله ډوډۍ له اسمانه څخه ورته دې ورکړلې د ګټ نه اوبه چې کله تږي شول ودې ویل هغوی ته چې ورننوځي ونیسي هغه ځمکه چې تا قسم کړی ؤ چې ورته وربه یې کړې', 'کله چې وزی شول هغوی تا ورته ورکرله دودی له اسمانه چخه ورته دې ورکرلې د ګت نه اوبه چې کله تزی شول ودې ویل هغوی ته چې ورننوجی ونیسی هغه جمکه چې تا قسم کری و چې ورته وربه یې کرې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39575, 'Nehemiah 9:16', 'Nehemiah', 9, 16, 'خو زمونږ نیکونه شول سرزوري مغرور سرغړونه یې وکړه ستا د امرونو څخه', 'خو زمونز نیکونه شول سرزوری مغرور سرغرونه یې وکره ستا د امرونو چخه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39576, 'Nehemiah 9:17', 'Nehemiah', 9, 17, 'سرغړونه یې وکړه ستا له اطاعته څخه هغوی کړې هېرې معجزې چې ښودلې وې تا هغوی د خپلې سرزورۍ په سبب کړلو یو مشر غوره چې د مصر غلامۍ ته بېرته بوځي هغوی خو ته بخښونکی خدای یې ته مهربانه او رحیم یې ته نه په قهرېږې ته زر لویه ده مینه تلپاتې ستا تا پرېنښودل هغوی', 'سرغرونه یې وکره ستا له اطاعته چخه هغوی کرې هېرې معجزې چې شودلې وې تا هغوی د خپلې سرزوری په سبب کرلو یو مشر غوره چې د مصر غلامی ته بېرته بوجی هغوی خو ته بخشونکی خدای یې ته مهربانه او رحیم یې ته نه په قهرېزې ته زر لویه ده مینه تلپاتې ستا تا پرېنشودل هغوی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39577, 'Nehemiah 9:18', 'Nehemiah', 9, 18, 'حتی جوړ کړ هغوی بت د خوسي په شکل او ویل یې چې دا هغه خدای دی چې یې راوویستئ له مصر څخه ای څښتنه! وکړ څومره سپکاوی ستا هغوی', 'حتی جور کر هغوی بت د خوسی په شکل او ویل یې چې دا هغه خدای دی چې یې راوویستی له مصر چخه ای چشتنه! وکر چومره سپکاوی ستا هغوی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nehemiah_9_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
